        array (
          'code' => '"SELECT d.id, d.uuid, d.entity_type, d.entity_id, t.code AS type_code, t.name AS type_name,\\n        d.description, d.original_name, d.extension, d.mime_type, d.size_bytes, d.sha256, d.storage_path, d.status,\\n        d.withdrawn_reason, d.withdrawn_at, d.uploaded_by, d.created_at,\\n        CONCAT(u.first_name, \' \', u.last_name) AS uploaded_by_name,\\n        CONCAT(w.first_name, \' \', w.last_name) AS withdrawn_by_name\\n        FROM documents d\\n        JOIN document_types t ON t.id = d.document_type_id\\n        JOIN users u ON u.id = d.uploaded_by\\n        LEFT JOIN users w ON w.id = d.withdrawn_by"',
